declare(strict_types=1);require_once __DIR__.'/_bootstrap.php';$products=ProductRepository::adminList($db);adminStart('Productos');?><p><a class="btn" href="/admin/producto.php">+ Nuevo producto</a></p><div class="table-wrap"><table class="table"><thead><tr><th>Foto</th><th>Producto</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($products as $product):?><tr><td><img class="thumb" src="<?=Security::e($product['imagen_url'])?>" alt=""></td><td><strong><?=Security::e($product['nombre'])?></strong><div class="muted"><?=Security::e($product['slug'])?></div></td><td>$<?=number_format((float)$product['precio'],0)?></td><td><?=(int)$product['stock']?></td><td><span class="badge <?=(int)$product['activo']?'on':'off'?>"><?=(int)$product['activo']?'Publicado':'Oculto'?></span></td><td class="actions"><a class="pill" href="/admin/producto.php?id=<?=(int)$product['id']?>">Editar</a><form method="post" action="/admin/eliminar-producto.php" onsubmit="return confirm('¿Eliminar este producto del catálogo?')"><input type="hidden" name="csrf" value="<?=Security::e(Security::csrfToken())?>"><input type="hidden" name="id" value="<?=(int)$product['id']?>"><button class="pill danger" type="submit">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php adminEnd();?>
